 "content": "def transform(grid):
    """Fill outlined squares; interior side length selects the fill color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    fill_for_side = {3: 8, 5: 4, 7: 3}
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if r2 - r1 != c2 - c1:
                        continue
                    side = r2 - r1 - 1
                    if side not in fill_for_side:
                        continue
                    if (all(grid[r1][c] == 2 for c in range(c1, c2 + 1)) and
                        all(grid[r2][c] == 2 for c in range(c1, c2 + 1)) and
                        all(grid[r][c1] == 2 for r in range(r1, r2 + 1)) and
                        all(grid[r][c2] == 2 for r in range(r1, r2 + 1))):
                        color = fill_for_side[side]
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                if out[r][c] == 0:
                                    out[r][c] = color
    return out
